    "timing": "untimed",
    "transcript": [
      {
        "at": 0,
        "label": "1",
        "text": "我叫小紅，佢係我朋友，叫阿細，喺一隻狗仔。",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 6,
        "label": "2",
        "text": "我成日同佢講我叻過佢，佢唔肯信。",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 10,
        "label": "3a",
        "text": "我笑笑口講：「你睇下！我有個鼻。」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 14,
        "label": "3b",
        "text": "阿細指住個鼻，同緊我講：「我都有啦。」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 19,
        "label": "4a",
        "text": "我話：「叻仔喎，噉你有冇耳仔先？」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 24,
        "label": "4b",
        "text": "佢又掂下自己隻耳仔，同緊我講：「你有嘅嘢我都有。」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 30,
        "label": "5a",
        "text": "我話：「你睇下我對眼幾大。」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 34,
        "label": "5b",
        "text": "佢慢慢企起身，眨下自己對眼，佢大啲。",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 39,
        "label": "6a",
        "text": "我話：「犀利喎！我有一對腳，你跟住我一齊跳好唔好？」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 45,
        "label": "6b",
        "text": "佢好開心噉跑跑跳跳，想同我講梗係冇問題啦。",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 51,
        "label": "7a",
        "text": "我話：「唉，你睇下我條脷幾短。」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 55,
        "label": "7b",
        "text": "佢坐咗喺度，望住自己條脷想講：「唔緊要，我都一樣噉短」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 62,
        "label": "8a",
        "text": "我話：「哈哈，多謝你。我係唔係醒過你啊？」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 68,
        "label": "8b",
        "text": "佢諗咗一陣，望一望我，想話佢醒啲。",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 72,
        "label": "9a",
        "text": "我話：「最後喇，我有一對手。」",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 76,
        "label": "9b",
        "text": "佢轉咗去後面，笑返我，佢有條尾，我冇。",
        "jyutping": "",
        "terms": []
      },
      {
        "at": 81,
        "label": "10",
        "text": "我哋好鍾意大家，日日都一齊玩。",
        "jyutping": "",
        "terms": []
      }
    ]
