    "id": "hbl-never-give-up",
    "title": "早晨",
    "englishTitle": "Never Give Up!",
    "source": "冚唪唥粵文讀本",
    "sourceId": "hbl",
    "collection": "分級故事",
    "episode": "Level 3 · 00007",
