    "transcriptAvailable": true,
    "isDemoNarration": false,
    "hasAuthenticAudio": true,
    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/the-rainbow-dinosaur-female",
    "sourceUrl": "https://hambaanglaang.hk/the-rainbow-dinosaur-who-drives-a-bus/",
