    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/00152the-night-the-moon-went-missing-child-lv4-hong-kong-urban-female",
    "sourceUrl": "https://hambaanglaang.hk/the-night-the-moon-went-missing/",
