    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/00105p_female",
    "sourceUrl": "https://hambaanglaang.hk/the-bear-who-loves-colour/",
    "textDocumentUrl": "https://docs.google.com/document/d/1fgPrCc6pcQp46LHRSXt3hovlNYPgdZ_eZE9kEtzP6F4/edit?usp=sharing",
    "pdfUrl": "",
