    "description": "What Is That Smell? · 站內收錄完整故事文字。",
    "transcriptAvailable": true,
    "isDemoNarration": false,
    "hasAuthenticAudio": true,
    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/00154pwhat-is-that-smell-child-lv4-hong-kong-urban-female",
    "sourceUrl": "https://hambaanglaang.hk/what-is-that-smell/",
    "textDocumentUrl": "https://docs.google.com/document/d/12iMVJvzce7b7Wa3Ifqip13F8FKeE42Em/edit?usp=sharing&ouid=114901914029474568085&rtpof=true&sd=true",
    "pdfUrl": "",
