    "description": "My Super Grandma · 站內收錄完整故事文字。",
    "transcriptAvailable": true,
    "isDemoNarration": false,
    "hasAuthenticAudio": true,
    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/00158pmy-super-grandma-child-lv4-hong-kong-urban-female",
    "sourceUrl": "https://hambaanglaang.hk/my-super-grandma/",
    "textDocumentUrl": "https://docs.google.com/document/d/17TDPOvEpEd8ozULnOErsVY3fIaTk7hwU/edit?usp=sharing&ouid=114901914029474568085&rtpof=true&sd=true",
    "pdfUrl": "",
