    "hasAuthenticAudio": true,
    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/00211dreams-of-jiang-yan-and-li-bai-child-lv6-hong-kong-urban-female",
    "sourceUrl": "https://hambaanglaang.hk/00211-2/",
    "textDocumentUrl": "https://docs.google.com/document/d/1h6QKQ2E9YQjbTy72pEAUH3kCcG-qFfHTBux-2O-aqfQ/edit?usp=sharing",
